    r = run(args=['-t', 'man'], stdin=b'[foo<https://example.com/?search=][ref]>\n\n[ref]: /uri\n')
    assert r.stdout == b'.PP\n[foohttps://example.com/?search=][ref] (https://example.com/?search=][ref])\n'
    assert r.stderr == b''
    assert r.returncode == 0


